<?php require 'inc/layout.php';$GLOBALS['seo']=['canonical'=>'recipes'];head('African Recipes with Ingredients You Can Buy | Skye African Supermarket','African recipes with every ingredient available at Skye African Supermarket. Add the whole list to your basket in one tap.');
$rs=db()->query("SELECT r.*,(SELECT COUNT(*) FROM recipe_items WHERE recipe_id=r.id) n FROM recipes r WHERE r.active=1 ORDER BY r.id")->fetchAll();?>
<main class="wrap1"><h1 class="ph1">Cook something good</h1><p>Pick a recipe and add every ingredient to your basket in one tap.</p><div class="tiles"><?php foreach($rs as $i=>$r): ?><a class="tile t<?=$i%3?>" href="recipe/<?=e($r['slug'])?>"><b><?=e($r['title'])?></b><small><?=e($r['intro'])?></small><small><?=$r['n']?> ingredients</small></a><?php endforeach; ?></div><?php if(!$rs)echo '<p>Recipes coming soon.</p>'; ?></main><?php foot();
